/usr/bin/bash -c python3 - << 'EOF'
import json
from weights_util import TokenizerVocab

tv = TokenizerVocab()
for s in ["```", "Here", "To", "You", "Below", "We", "Sure", "Certainly", "Let", "In", "\n", "\n\n", "\n\n\n", "\n    \n", "\n   \n", "\n        \n"]:
    print(f"  {repr(s):16s} -> id={tv.str_to_id(s)}")

# Also check every distinct model top1 at EOL of return statements in acts/token_stats_0.json!
ts = json.load(open("/workspace/work/acts/token_stats_0.json"))
ret_top1s = set()
for rec in ts:
    toks, top1s = rec["tokens"], rec["top1"]
    for p, t in enumerate(toks):
        if "return" in t:
            q = p + 1
            while q < len(toks) and "\n" not in toks[q]:
                q += 1
            if q < len(toks):
                ret_top1s.add(top1s[q])
print("Distinct top1 tokens at return EOLs in token_stats_0:", [(repr(x), tv.str_to_id(x)) for x in sorted(ret_top1s)])
EOF
